"use client"

/**
 * Clean-room routing desk. The layout and motion were observed in a public
 * post that ships no code and no license. No source, sample payload, or asset
 * was copied. The host applies the policy through onDeployRequest.
 */

import * as React from "react"
import { ArrowDown, ArrowUp, LoaderCircle, Plus, X } from "lucide-react"
import { motion, useReducedMotion } from "motion/react"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Separator } from "@/components/ui/separator"
import { Skeleton } from "@/components/ui/skeleton"
import { Slider } from "@/components/ui/slider"
import { Switch } from "@/components/ui/switch"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { cn } from "@/lib/utils"
import { formatRouterAmount } from "@/lib/model-router-cost"
import {
  addFallback,
  blendedCost,
  canDeploy,
  diffPolicy,
  moveFallback,
  removeFallback,
  validatePolicy,
  weightedErrorRate,
  weightedP95,
  withFallbackEnabled,
  withPreset,
  withShare,
  type PolicyChange,
  type PolicyIssue,
  type RouterEnvironment,
  type RouterPolicy,
  type RoutingPreset,
} from "@/lib/model-router"
import { EmptyState } from "@/components/ui/empty-state"
import { SegmentedControl } from "@/components/ui/segmented-control"
import { StatusPill } from "@/components/ui/status-pill"

export type ModelRouterStatus = "ready" | "loading" | "error"

export type ModelRouterDeployPhase = "pending" | "success" | "error"

export type ModelRouterClassNames = {
  root?: string
  diagram?: string
  table?: string
}

export type ModelRouterLabels = {
  title: string
  environment: string
  blended: string
  perThousand: string
  vsLive: string
  sameAsLive: string
  incomplete: string
  preset: string
  cost: string
  balanced: string
  quality: string
  diagram: string
  gateway: string
  routes: string
  model: string
  share: string
  latency: string
  price: string
  errors: string
  fallback: string
  fallbackHint: string
  moveUp: string
  moveDown: string
  removeFallback: string
  addFallback: string
  unsaved: string
  live: string
  deploy: string
  deploying: string
  deployed: string
  deployError: string
  readOnly: string
  emptyTitle: string
  emptyDescription: string
  loading: string
  errorTitle: string
  shareInvalid: string
  noMetrics: string
  diffPreset: string
  diffEnvironment: string
  diffFallbackOn: string
  diffFallbackOff: string
  diffFallbackOrder: string
  diffRouteAdded: string
  diffRouteRemoved: string
  shareLabel: (name: string) => string
  missingMetrics: (name: string) => string
  fallbackDuplicate: (name: string) => string
  fallbackCycle: (name: string) => string
  fallbackUnknown: (name: string) => string
  diagramSummary: (parts: string) => string
  diffShare: (name: string, from: number, to: number) => string
  chainLabel: (name: string, index: number, total: number) => string
}

export type ModelRouterProps = {
  policy: RouterPolicy
  deployed: RouterPolicy
  environments: readonly RouterEnvironment[]
  onPolicyChange: (policy: RouterPolicy) => void
  onDeployRequest: (policy: RouterPolicy) => Promise<void>
  onEnvironmentChange?: (environmentId: string) => void
  status?: ModelRouterStatus
  readOnly?: boolean
  error?: string
  labels?: Partial<ModelRouterLabels>
  /** BCP 47 tag for `Intl` money and percents. */
  locale?: string
  /** ISO 4217 code. The amounts on each route are already in this currency. */
  currency?: string
  deployPhase?: ModelRouterDeployPhase
  className?: string
  classNames?: ModelRouterClassNames
}

const TONE = ["text-chart-1", "text-chart-2", "text-chart-3", "text-chart-4", "text-chart-5"] as const

const defaultLabels: ModelRouterLabels = {
  title: "Model router",
  environment: "Environment",
  blended: "Blended cost",
  perThousand: "per 1K tokens",
  vsLive: "vs live",
  sameAsLive: "Same as live",
  incomplete: "Incomplete price",
  preset: "Routing preset",
  cost: "Cost",
  balanced: "Balanced",
  quality: "Quality",
  diagram: "Traffic split",
  gateway: "Gateway",
  routes: "Routes",
  model: "Model",
  share: "Share",
  latency: "p95 / p99",
  price: "USD / 1K",
  errors: "Errors",
  fallback: "Fallback",
  fallbackHint: "If the first model fails, try the next.",
  moveUp: "Move up",
  moveDown: "Move down",
  removeFallback: "Remove from fallback",
  addFallback: "Add to fallback",
  unsaved: "Unsaved changes",
  live: "Live",
  deploy: "Deploy policy",
  deploying: "Deploying policy",
  deployed: "Policy deployed",
  deployError: "The policy was not deployed. The editor shows this draft again.",
  readOnly: "You can view this policy. Deploy is not available for this role.",
  emptyTitle: "No models",
  emptyDescription: "The catalog has no models to route yet.",
  loading: "Loading the policy",
  errorTitle: "The policy did not load",
  shareInvalid: "Shares must add up to 100%.",
  noMetrics: "No metrics",
  diffPreset: "Preset",
  diffEnvironment: "Environment",
  diffFallbackOn: "Fallback on",
  diffFallbackOff: "Fallback off",
  diffFallbackOrder: "Fallback order",
  diffRouteAdded: "Route added",
  diffRouteRemoved: "Route removed",
  shareLabel: (name) => `Share for ${name}`,
  missingMetrics: (name) => `${name} has no metrics`,
  fallbackDuplicate: (name) => `${name} is listed twice in the fallback`,
  fallbackCycle: (name) => `The fallback returns to ${name}`,
  fallbackUnknown: (name) => `${name} is not a route`,
  diagramSummary: (parts) => `Traffic split. ${parts}`,
  diffShare: (name, from, to) => `${name} share ${from}% to ${to}%`,
  chainLabel: (name, index, total) => `${name}, step ${index} of ${total}`,
}

function labelsFrom(partial?: Partial<ModelRouterLabels>): ModelRouterLabels {
  return { ...defaultLabels, ...partial }
}

function percent(value: number, locale: string) {
  return new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 2 }).format(value)
}

function seconds(ms: number) {
  return (ms / 1000).toFixed(2)
}

function shortName(name: string) {
  return name.length > 22 ? `${name.slice(0, 21)}…` : name
}

function issueText(issue: PolicyIssue, policy: RouterPolicy, labels: ModelRouterLabels) {
  const name = policy.routes.find((route) => route.id === issue.modelId)?.name ?? issue.modelId ?? ""
  if (issue.code === "shares") return labels.shareInvalid
  if (issue.code === "missing-metrics") return labels.missingMetrics(name)
  if (issue.code === "fallback-duplicate") return labels.fallbackDuplicate(name)
  if (issue.code === "fallback-cycle") return labels.fallbackCycle(name)
  return labels.fallbackUnknown(name)
}

function changeText(change: PolicyChange, policy: RouterPolicy, deployed: RouterPolicy, labels: ModelRouterLabels) {
  const nameOf = (id: string) =>
    policy.routes.find((route) => route.id === id)?.name ??
    deployed.routes.find((route) => route.id === id)?.name ??
    id
  if (change.kind === "preset") return `${labels.diffPreset}: ${change.from} → ${change.to}`
  if (change.kind === "environment") return `${labels.diffEnvironment}: ${change.from} → ${change.to}`
  if (change.kind === "share") return labels.diffShare(nameOf(change.modelId), change.from, change.to)
  if (change.kind === "fallback-enabled") return change.to ? labels.diffFallbackOn : labels.diffFallbackOff
  if (change.kind === "fallback-order") return labels.diffFallbackOrder
  if (change.kind === "route-added") return `${labels.diffRouteAdded}: ${nameOf(change.modelId)}`
  return `${labels.diffRouteRemoved}: ${nameOf(change.modelId)}`
}

function useQuietMotion() {
  const fromConfig = useReducedMotion()
  const [fromMedia, setFromMedia] = React.useState(
    () => typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches,
  )
  React.useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)")
    const update = () => setFromMedia(query.matches)
    update()
    query.addEventListener("change", update)
    return () => query.removeEventListener("change", update)
  }, [])
  return fromConfig === true || fromMedia
}

function FlowDiagram({
  policy,
  labels,
  className,
}: {
  policy: RouterPolicy
  labels: ModelRouterLabels
  className?: string
}) {
  const reduced = useQuietMotion()
  const allowParticles = !reduced
  const routes = policy.routes
  const height = Math.max(168, routes.length * 32 + 24)
  const sourceY = height / 2
  const rowHeight = routes.length ? (height - 24) / routes.length : 0
  const summary = labels.diagramSummary(
    routes.map((route) => `${route.name} ${route.share}%`).join(". "),
  )
  const summaryId = React.useId()

  return (
    <figure className={cn("min-w-0", className)} aria-labelledby={summaryId} data-particles={allowParticles ? "on" : "off"}>
      <figcaption id={summaryId} className="sr-only">
        {summary}
      </figcaption>
      <svg viewBox={`0 0 640 ${height}`} className="h-auto w-full" role="presentation" aria-hidden="true">
        <text x={16} y={sourceY} dominantBaseline="middle" className="fill-current text-xs text-muted-foreground">
          {labels.gateway}
        </text>
        {routes.map((route, index) => {
          const y = 12 + rowHeight * index + rowHeight / 2
          const tone = TONE[index % TONE.length] ?? "text-foreground"
          const width = route.share <= 0 ? 0 : Math.max(2, (route.share / 100) * 22)
          const midX = 300
          return (
            <g key={route.id}>
              {width > 0 ? (
                <path
                  d={`M 88 ${sourceY} C ${midX} ${sourceY}, ${midX} ${y}, 470 ${y}`}
                  fill="none"
                  strokeWidth={width}
                  strokeLinecap="round"
                  className={cn("stroke-current opacity-80", tone)}
                />
              ) : null}
              <text x={488} y={y} dominantBaseline="middle" className="fill-current text-xs text-foreground">
                {shortName(route.name)}
                <title>{`${route.name} ${route.share}%`}</title>
              </text>
              <text x={624} y={y} textAnchor="end" dominantBaseline="middle" className="fill-current text-xs text-muted-foreground tabular-nums">
                {route.share}%
              </text>
              {allowParticles && width > 0 && index < 6 ? (
                <motion.circle
                  r={3}
                  className={cn("fill-current", tone)}
                  data-particle="true"
                  initial={{ opacity: 0 }}
                  animate={{
                    x: [88, midX, 470],
                    y: [sourceY, (sourceY + y) / 2, y],
                    opacity: [0, 0.95, 0],
                  }}
                  transition={{ duration: 2.8, repeat: Infinity, delay: index * 0.35, ease: "linear" }}
                />
              ) : null}
            </g>
          )
        })}
      </svg>
    </figure>
  )
}

export function ModelRouter({
  policy,
  deployed,
  environments,
  onPolicyChange,
  onDeployRequest,
  onEnvironmentChange,
  status = "ready",
  readOnly = false,
  error,
  labels: labelOverride,
  locale = "en-US",
  currency = "USD",
  deployPhase,
  className,
  classNames,
}: ModelRouterProps) {
  const labels = labelsFrom(labelOverride)
  const fallbackLabelId = React.useId()
  const [localPhase, setLocalPhase] = React.useState<"idle" | ModelRouterDeployPhase>("idle")
  const [banner, setBanner] = React.useState<"success" | "error" | null>(null)
  const [fallbackPick, setFallbackPick] = React.useState("")
  const mounted = React.useRef(true)
  React.useEffect(() => {
    mounted.current = true
    return () => {
      mounted.current = false
    }
  }, [])

  const phase = localPhase !== "idle" ? localPhase : (deployPhase ?? "idle")
  const locked = readOnly || phase === "pending" || status !== "ready"
  const changes = diffPolicy(deployed, policy)
  const issues = validatePolicy(policy)
  const valid = canDeploy(policy)
  const dirty = changes.length > 0
  const blend = blendedCost(policy.routes)
  const baseline = blendedCost(deployed.routes)
  const money = (amount: number) => formatRouterAmount(amount, { locale, currency })
  const delta = baseline.amountPer1k > 0 ? (blend.amountPer1k - baseline.amountPer1k) / baseline.amountPer1k : null
  const p95 = weightedP95(policy.routes)
  const errorRate = weightedErrorRate(policy.routes)
  const available = policy.routes.filter((route) => !policy.fallback.modelIds.includes(route.id))

  function commit(next: RouterPolicy) {
    setBanner(null)
    setLocalPhase("idle")
    onPolicyChange(next)
  }

  async function deploy() {
    if (!valid || readOnly || phase === "pending") return
    const snapshot = policy
    setBanner(null)
    setLocalPhase("pending")
    try {
      await onDeployRequest(snapshot)
      if (mounted.current) {
        setLocalPhase("idle")
        setBanner("success")
      }
    } catch {
      if (!mounted.current) return
      setLocalPhase("idle")
      setBanner("error")
      onPolicyChange(snapshot)
    }
  }

  function onEnvironment(next: string) {
    if (onEnvironmentChange) onEnvironmentChange(next)
    else commit({ ...policy, environmentId: next })
  }

  return (
    <section
      aria-busy={status === "loading" || phase === "pending"}
      data-readonly={readOnly ? "true" : "false"}
      data-deploy={phase}
      data-unsaved={dirty ? "true" : "false"}
      className={cn("flex min-w-0 flex-col gap-4 rounded-xl border border-border bg-card p-4 text-card-foreground shadow-sm", className, classNames?.root)}
    >
      <header className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <h2 className="text-base font-medium text-balance">{labels.title}</h2>
        <Select value={policy.environmentId} onValueChange={onEnvironment} disabled={locked || environments.length === 0}>
          <SelectTrigger aria-label={labels.environment} className="w-full sm:w-44">
            <SelectValue placeholder={labels.environment}>
              {environments.find((item) => item.id === policy.environmentId)?.label}
            </SelectValue>
          </SelectTrigger>
          <SelectContent>
            <SelectGroup>
              {environments.map((environment) => (
                <SelectItem key={environment.id} value={environment.id}>
                  {environment.label}
                </SelectItem>
              ))}
            </SelectGroup>
          </SelectContent>
        </Select>
      </header>

      {status === "loading" ? (
        <div className="flex flex-col gap-3" aria-label={labels.loading}>
          <Skeleton className="h-16 w-40" />
          <Skeleton className="h-40 w-full" />
          <Skeleton className="h-24 w-full" />
        </div>
      ) : null}

      {status === "error" ? (
        <Alert variant="destructive">
          <AlertTitle>{labels.errorTitle}</AlertTitle>
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      ) : null}

      {status === "ready" && policy.routes.length === 0 ? (
        <EmptyState title={labels.emptyTitle} description={labels.emptyDescription} />
      ) : null}

      {status === "ready" && policy.routes.length > 0 ? (
        <>
          <div className="flex flex-col gap-3 lg:flex-row lg:items-end lg:justify-between">
            <div className="min-w-0">
              <p className="text-xs text-muted-foreground">{labels.blended}</p>
              <p className="text-3xl font-medium tabular-nums tracking-tight">{money(blend.amountPer1k)}</p>
              <p className="text-xs text-muted-foreground tabular-nums">
                {labels.perThousand}
                {delta == null ? null : delta === 0 ? ` · ${labels.sameAsLive}` : ` · ${delta > 0 ? "+" : "−"}${percent(Math.abs(delta), locale)} ${labels.vsLive}`}
                {blend.complete ? null : ` · ${labels.incomplete}`}
                {p95 == null ? null : ` · p95 ${seconds(p95)}`}
                {errorRate == null ? null : ` · ${percent(errorRate, locale)}`}
              </p>
            </div>
            <SegmentedControl
              label={labels.preset}
              value={policy.preset}
              onValueChange={(value) => {
                if (value === "cost" || value === "balanced" || value === "quality") commit(withPreset(policy, value))
              }}
              options={(["cost", "balanced", "quality"] as const satisfies readonly RoutingPreset[]).map((value) => ({
                value,
                label: labels[value],
              }))}
            />
          </div>

          <div className={cn("max-h-80 overflow-auto", classNames?.diagram)}>
            <FlowDiagram policy={policy} labels={labels} />
          </div>

          <div className={cn("min-w-0 overflow-x-auto", classNames?.table)}>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>{labels.model}</TableHead>
                  <TableHead>{labels.share}</TableHead>
                  <TableHead>{labels.latency}</TableHead>
                  <TableHead>{labels.price}</TableHead>
                  <TableHead>{labels.errors}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {policy.routes.map((route, index) => {
                  const tone = TONE[index % TONE.length]
                  return (
                    <TableRow key={route.id}>
                      <TableCell className="max-w-40 min-w-0">
                        <span className={cn("block truncate font-medium", tone)} title={route.name}>
                          {route.name}
                        </span>
                        <span className="block truncate text-xs text-muted-foreground" title={route.vendor}>
                          {route.vendor}
                        </span>
                      </TableCell>
                      <TableCell className="min-w-36">
                        <div className="flex items-center gap-2">
                          <label className="flex min-w-0 flex-1 items-center">
                            <span className="sr-only">{labels.shareLabel(route.name)}</span>
                            <Slider
                              aria-label={labels.shareLabel(route.name)}
                              aria-valuetext={`${route.share}%`}
                              min={0}
                              max={100}
                              step={1}
                              value={[route.share]}
                              disabled={locked || policy.routes.length < 2}
                              className="w-full touch-pan-y"
                              onValueChange={(value) => {
                                const next = value[0]
                                if (next == null) return
                                commit(withShare(policy, route.id, next))
                              }}
                            />
                          </label>
                          <span className="w-10 shrink-0 text-right text-xs tabular-nums">{route.share}%</span>
                        </div>
                      </TableCell>
                      <TableCell className="tabular-nums">
                        {route.metrics ? `${seconds(route.metrics.p95Ms)} / ${seconds(route.metrics.p99Ms)}` : labels.noMetrics}
                      </TableCell>
                      <TableCell className="tabular-nums">{route.metrics ? money(route.metrics.amountPer1k) : labels.noMetrics}</TableCell>
                      <TableCell className="tabular-nums">{route.metrics ? percent(route.metrics.errorRate, locale) : labels.noMetrics}</TableCell>
                    </TableRow>
                  )
                })}
              </TableBody>
            </Table>
          </div>

          {issues.length > 0 ? (
            <ul className="flex flex-col gap-1 text-sm text-destructive">
              {issues.map((issue, index) => (
                <li key={`${issue.code}-${issue.modelId ?? index}`}>{issueText(issue, policy, labels)}</li>
              ))}
            </ul>
          ) : null}

          <Separator />

          <div className="flex flex-col gap-3">
            <div className="flex items-center justify-between gap-3">
              <div className="min-w-0">
                <p className="text-sm font-medium" id={fallbackLabelId}>
                  {labels.fallback}
                </p>
                <p className="text-xs text-pretty text-muted-foreground">{labels.fallbackHint}</p>
              </div>
              <Switch
                checked={policy.fallback.enabled}
                onCheckedChange={(checked) => commit(withFallbackEnabled(policy, checked))}
                disabled={locked}
                aria-labelledby={fallbackLabelId}
              />
            </div>
            {policy.fallback.enabled ? (
              <ol aria-label={labels.fallback} className="flex flex-col gap-2">
                {policy.fallback.modelIds.map((modelId, index) => {
                  const name = policy.routes.find((route) => route.id === modelId)?.name ?? modelId
                  const total = policy.fallback.modelIds.length
                  return (
                    <li
                      key={`${modelId}-${index}`}
                      tabIndex={locked ? -1 : 0}
                      aria-keyshortcuts="ArrowUp ArrowDown"
                      aria-label={labels.chainLabel(name, index + 1, total)}
                      className="flex min-w-0 items-center gap-2 rounded-md border border-border px-2 py-1 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
                      onKeyDown={(event) => {
                        if (event.target !== event.currentTarget || locked) return
                        if (event.key === "ArrowUp") {
                          event.preventDefault()
                          commit(moveFallback(policy, index, -1))
                        }
                        if (event.key === "ArrowDown") {
                          event.preventDefault()
                          commit(moveFallback(policy, index, 1))
                        }
                      }}
                    >
                      <span className="min-w-0 flex-1 truncate text-sm" title={name}>
                        {index + 1}. {name}
                      </span>
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        aria-label={`${labels.moveUp} ${name}`}
                        disabled={locked || index === 0}
                        onClick={() => commit(moveFallback(policy, index, -1))}
                      >
                        <ArrowUp />
                      </Button>
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        aria-label={`${labels.moveDown} ${name}`}
                        disabled={locked || index === total - 1}
                        onClick={() => commit(moveFallback(policy, index, 1))}
                      >
                        <ArrowDown />
                      </Button>
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        aria-label={`${labels.removeFallback} ${name}`}
                        disabled={locked}
                        onClick={() => commit(removeFallback(policy, modelId))}
                      >
                        <X />
                      </Button>
                    </li>
                  )
                })}
              </ol>
            ) : null}
            {policy.fallback.enabled && available.length > 0 ? (
              <div className="flex flex-col gap-2 sm:flex-row">
                <Select value={fallbackPick} onValueChange={setFallbackPick} disabled={locked}>
                  <SelectTrigger aria-label={labels.addFallback} className="w-full sm:w-56">
                    <SelectValue placeholder={labels.addFallback}>
                      {available.find((route) => route.id === fallbackPick)?.name}
                    </SelectValue>
                  </SelectTrigger>
                  <SelectContent>
                    <SelectGroup>
                      {available.map((route) => (
                        <SelectItem key={route.id} value={route.id}>
                          {route.name}
                        </SelectItem>
                      ))}
                    </SelectGroup>
                  </SelectContent>
                </Select>
                <Button
                  type="button"
                  variant="outline"
                  disabled={locked || fallbackPick === ""}
                  onClick={() => {
                    commit(addFallback(policy, fallbackPick))
                    setFallbackPick("")
                  }}
                >
                  <Plus data-icon="inline-start" />
                  {labels.addFallback}
                </Button>
              </div>
            ) : null}
          </div>
        </>
      ) : null}

      {readOnly ? <p className="text-sm text-muted-foreground">{labels.readOnly}</p> : null}
      {banner === "error" || phase === "error" ? (
        <Alert variant="destructive">
          <AlertTitle>{labels.deployError}</AlertTitle>
          {error ? <AlertDescription>{error}</AlertDescription> : null}
        </Alert>
      ) : null}
      {banner === "success" || phase === "success" ? <StatusPill label={labels.deployed} tone="positive" /> : null}

      {status === "ready" && changes.length > 0 ? (
        <ul aria-label={labels.unsaved} className="flex flex-col gap-1 text-xs text-muted-foreground">
          {changes.map((change, index) => (
            <li key={`${change.kind}-${index}`}>{changeText(change, policy, deployed, labels)}</li>
          ))}
        </ul>
      ) : null}

      <footer className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex min-w-0 flex-wrap items-center gap-2">
          <span className="truncate text-xs text-muted-foreground" title={policy.name}>
            {policy.name}
          </span>
          {dirty ? <StatusPill label={labels.unsaved} tone="warning" /> : <StatusPill label={labels.live} tone="positive" />}
        </div>
        {readOnly ? null : (
          <Button type="button" disabled={!dirty || !valid || locked} onClick={() => void deploy()}>
            {phase === "pending" ? <LoaderCircle className="animate-spin motion-reduce:animate-none" data-icon="inline-start" /> : null}
            {phase === "pending" ? labels.deploying : labels.deploy}
          </Button>
        )}
      </footer>
    </section>
  )
}

/**
 * Routing policy for a host CRM. Pure data: no theme, no fetch.
 * Clean-room. The interaction was observed; no source or sample payload was copied.
 *
 * Per-1K blending lives in `model-router-cost.ts`. That module is the candidate
 * call site for the cost-waterfall pricing core. This file does not price
 * input, output, or cache rates, and it does not draw a cost-by-step chart.
 */

import { blendCostPer1k } from "@/lib/model-router-cost"

export const ROUTING_PRESETS = ["cost", "balanced", "quality"] as const

export type RoutingPreset = (typeof ROUTING_PRESETS)[number]

export type ModelMetrics = {
  /** Milliseconds. */
  p95Ms: number
  /** Milliseconds. */
  p99Ms: number
  /**
   * Amount per 1,000 tokens in the policy currency.
   * The host fills this. Pricing per 1M (input, output, cache read, cache write)
   * belongs to the cost-waterfall core; see `blendCostPer1k`.
   */
  amountPer1k: number
  /** Fraction from 0 to 1. */
  errorRate: number
}

export type ModelRoute = {
  id: string
  name: string
  vendor: string
  /** Integer percent. A normalized policy sums to 100. */
  share: number
  metrics?: ModelMetrics
}

export type FallbackChain = {
  enabled: boolean
  /** Ordered model ids. The first id is tried first. */
  modelIds: readonly string[]
}

export type RouterEnvironment = {
  id: string
  label: string
}

export type RouterPolicy = {
  id: string
  name: string
  environmentId: string
  preset: RoutingPreset
  routes: readonly ModelRoute[]
  fallback: FallbackChain
}

export type PolicyIssueCode =
  | "shares"
  | "fallback-duplicate"
  | "fallback-cycle"
  | "fallback-unknown"
  | "missing-metrics"

export type PolicyIssue = {
  code: PolicyIssueCode
  modelId?: string
}

export type PolicyChange =
  | { kind: "preset"; from: RoutingPreset; to: RoutingPreset }
  | { kind: "environment"; from: string; to: string }
  | { kind: "share"; modelId: string; from: number; to: number }
  | { kind: "fallback-enabled"; from: boolean; to: boolean }
  | { kind: "fallback-order"; from: readonly string[]; to: readonly string[] }
  | { kind: "route-added"; modelId: string }
  | { kind: "route-removed"; modelId: string }

export type BlendedCost = {
  /** Amount per 1K tokens across the shares that have a price, in the policy currency. */
  amountPer1k: number
  /** Percent points included in the blend. */
  coveredShare: number
  /** True when every percent point has a price. */
  complete: boolean
}

const PRICE_FLOOR = 0.000001

function cloneRoute(route: ModelRoute, share: number): ModelRoute {
  if (route.metrics) return { ...route, share, metrics: { ...route.metrics } }
  return { ...route, share }
}

/** Largest remainder. Ties go to the earlier index. */
export function allocateInteger(total: number, weights: readonly number[]): number[] {
  const count = weights.length
  if (count === 0 || total <= 0) return weights.map(() => 0)
  const safe = weights.map((weight) => (Number.isFinite(weight) && weight > 0 ? weight : 0))
  const sum = safe.reduce((acc, weight) => acc + weight, 0)
  const raw =
    sum > 0
      ? safe.map((weight) => (total * weight) / sum)
      : safe.map(() => total / count)
  const floors = raw.map((value) => Math.floor(value))
  let left = total - floors.reduce((acc, value) => acc + value, 0)
  const order = raw
    .map((value, index) => ({ index, fraction: value - Math.floor(value) }))
    .sort((a, b) => b.fraction - a.fraction || a.index - b.index)
  for (const entry of order) {
    if (left <= 0) break
    const current = floors[entry.index]
    if (current == null) continue
    floors[entry.index] = current + 1
    left -= 1
  }
  return floors
}

function weightsFor(routes: readonly ModelRoute[], preset: RoutingPreset): number[] {
  if (preset === "balanced") return routes.map(() => 1)
  return routes.map((route) => {
    const metrics = route.metrics
    if (!metrics) return 0
    if (preset === "cost") return 1 / Math.max(metrics.amountPer1k, PRICE_FLOOR)
    return 1 / (metrics.errorRate * 1000 + Math.max(metrics.p95Ms, 1))
  })
}

export function applyPreset(routes: readonly ModelRoute[], preset: RoutingPreset): ModelRoute[] {
  if (routes.length === 0) return []
  if (routes.length === 1) {
    const only = routes[0]
    return only ? [cloneRoute(only, 100)] : []
  }
  const shares = allocateInteger(100, weightsFor(routes, preset))
  return routes.map((route, index) => cloneRoute(route, shares[index] ?? 0))
}

/**
 * Sets one share and redistributes the rest.
 * The edited share is kept (clamped to an integer 0–100). The other shares
 * keep their ratios. An all-zero remainder is split evenly, earliest index first.
 */
export function setRouteShare(routes: readonly ModelRoute[], routeId: string, nextShare: number): ModelRoute[] {
  if (routes.length === 0) return []
  if (routes.length === 1) {
    const only = routes[0]
    return only ? [cloneRoute(only, 100)] : []
  }
  const index = routes.findIndex((route) => route.id === routeId)
  if (index < 0) return routes.map((route) => cloneRoute(route, route.share))
  const clamped = Math.min(100, Math.max(0, Math.round(nextShare)))
  const others = routes.filter((route) => route.id !== routeId)
  const assigned = allocateInteger(
    100 - clamped,
    others.map((route) => route.share),
  )
  let cursor = 0
  return routes.map((route) => {
    if (route.id === routeId) return cloneRoute(route, clamped)
    const share = assigned[cursor] ?? 0
    cursor += 1
    return cloneRoute(route, share)
  })
}

export function blendedCost(routes: readonly ModelRoute[]): BlendedCost {
  const priced = routes.flatMap((route) =>
    route.metrics ? [{ share: route.share, amountPer1k: route.metrics.amountPer1k }] : [],
  )
  const amountPer1k = blendCostPer1k(priced)
  const coveredShare = priced.reduce((sum, slice) => sum + slice.share, 0)
  const complete = routes.length === 0 || coveredShare === 100
  return { amountPer1k, coveredShare, complete }
}

export function weightedP95(routes: readonly ModelRoute[]): number | null {
  let weight = 0
  let total = 0
  for (const route of routes) {
    if (!route.metrics || route.share <= 0) continue
    weight += route.share
    total += route.share * route.metrics.p95Ms
  }
  if (weight === 0) return null
  return total / weight
}

export function weightedErrorRate(routes: readonly ModelRoute[]): number | null {
  let weight = 0
  let total = 0
  for (const route of routes) {
    if (!route.metrics || route.share <= 0) continue
    weight += route.share
    total += route.share * route.metrics.errorRate
  }
  if (weight === 0) return null
  return total / weight
}

export function validatePolicy(policy: RouterPolicy): PolicyIssue[] {
  const issues: PolicyIssue[] = []
  const sum = policy.routes.reduce((acc, route) => acc + route.share, 0)
  const sharesBroken =
    policy.routes.some((route) => !Number.isInteger(route.share) || route.share < 0 || route.share > 100) ||
    (policy.routes.length > 0 ? sum !== 100 : sum !== 0)
  if (sharesBroken) issues.push({ code: "shares" })

  for (const route of policy.routes) {
    if (!route.metrics) issues.push({ code: "missing-metrics", modelId: route.id })
  }

  const known = new Set(policy.routes.map((route) => route.id))
  const seen = new Set<string>()
  for (const modelId of policy.fallback.modelIds) {
    if (!known.has(modelId)) issues.push({ code: "fallback-unknown", modelId })
    if (seen.has(modelId)) {
      issues.push({ code: "fallback-duplicate", modelId })
      issues.push({ code: "fallback-cycle", modelId })
    } else {
      seen.add(modelId)
    }
  }
  return issues
}

export function canDeploy(policy: RouterPolicy): boolean {
  return validatePolicy(policy).length === 0 && policy.routes.length > 0
}

function sameIds(left: readonly string[], right: readonly string[]) {
  return left.length === right.length && left.every((id, index) => id === right[index])
}

export function diffPolicy(deployed: RouterPolicy, draft: RouterPolicy): PolicyChange[] {
  const changes: PolicyChange[] = []
  if (deployed.preset !== draft.preset) changes.push({ kind: "preset", from: deployed.preset, to: draft.preset })
  if (deployed.environmentId !== draft.environmentId) {
    changes.push({ kind: "environment", from: deployed.environmentId, to: draft.environmentId })
  }
  const deployedRoutes = new Map(deployed.routes.map((route) => [route.id, route]))
  const draftRoutes = new Map(draft.routes.map((route) => [route.id, route]))
  for (const route of draft.routes) {
    const previous = deployedRoutes.get(route.id)
    if (!previous) changes.push({ kind: "route-added", modelId: route.id })
    else if (previous.share !== route.share) {
      changes.push({ kind: "share", modelId: route.id, from: previous.share, to: route.share })
    }
  }
  for (const route of deployed.routes) {
    if (!draftRoutes.has(route.id)) changes.push({ kind: "route-removed", modelId: route.id })
  }
  if (deployed.fallback.enabled !== draft.fallback.enabled) {
    changes.push({ kind: "fallback-enabled", from: deployed.fallback.enabled, to: draft.fallback.enabled })
  }
  if (!sameIds(deployed.fallback.modelIds, draft.fallback.modelIds)) {
    changes.push({ kind: "fallback-order", from: deployed.fallback.modelIds, to: draft.fallback.modelIds })
  }
  return changes
}

export function withPreset(policy: RouterPolicy, preset: RoutingPreset): RouterPolicy {
  return { ...policy, preset, routes: applyPreset(policy.routes, preset) }
}

export function withShare(policy: RouterPolicy, routeId: string, share: number): RouterPolicy {
  return { ...policy, routes: setRouteShare(policy.routes, routeId, share) }
}

export function withFallbackEnabled(policy: RouterPolicy, enabled: boolean): RouterPolicy {
  return { ...policy, fallback: { ...policy.fallback, enabled } }
}

export function moveFallback(policy: RouterPolicy, index: number, direction: -1 | 1): RouterPolicy {
  const ids = [...policy.fallback.modelIds]
  const next = index + direction
  const current = ids[index]
  const swap = ids[next]
  if (current == null || swap == null) return policy
  ids[index] = swap
  ids[next] = current
  return { ...policy, fallback: { ...policy.fallback, modelIds: ids } }
}

export function removeFallback(policy: RouterPolicy, modelId: string): RouterPolicy {
  return {
    ...policy,
    fallback: { ...policy.fallback, modelIds: policy.fallback.modelIds.filter((id) => id !== modelId) },
  }
}

export function addFallback(policy: RouterPolicy, modelId: string): RouterPolicy {
  if (policy.fallback.modelIds.includes(modelId)) return policy
  if (!policy.routes.some((route) => route.id === modelId)) return policy
  return { ...policy, fallback: { ...policy.fallback, modelIds: [...policy.fallback.modelIds, modelId] } }
}

/**
 * Local per-1K blend for the model router. Kept in its own module so the
 * router can later call the cost-waterfall pricing core without growing a
 * second pricer.
 *
 * Candidate: `cost-waterfall` (separate branch, not imported here) will expose
 * an injectable core priced per 1M tokens — input, output, cache read, and
 * cache write — with a configurable currency. When that core is on CPL, the
 * host should turn those four rates into one `amountPer1k` and pass it in.
 * This function only weights shares. It does not price those rates, convert
 * currencies, or describe cost per step.
 *
 * Display goes through `formatRouterAmount` (`Intl.NumberFormat`). The amount
 * is already in `currency`. USD and MXN are both valid codes; the formatter
 * does not assume one of them.
 */

export type CostSlice = {
  /** Traffic share in percent points. */
  share: number
  /** Amount per 1,000 tokens, already in the caller's currency. */
  amountPer1k: number
}

/** Share-weighted amount per 1K. Missing or non-finite slices contribute nothing. */
export function blendCostPer1k(slices: readonly CostSlice[]): number {
  let total = 0
  for (const slice of slices) {
    if (!Number.isFinite(slice.share) || !Number.isFinite(slice.amountPer1k)) continue
    total += (slice.share / 100) * slice.amountPer1k
  }
  return total
}

export type RouterMoneyFormat = {
  locale: string
  currency: string
}

/** Formats a per-1K amount. Fraction digits stay at 4 so small token prices remain visible. */
export function formatRouterAmount(amount: number, format: RouterMoneyFormat): string {
  return new Intl.NumberFormat(format.locale, {
    style: "currency",
    currency: format.currency,
    minimumFractionDigits: 4,
    maximumFractionDigits: 4,
  }).format(amount)
}
